import { useMemo, useState } from 'react';
import {
  useReactTable,
  getCoreRowModel,
  getPaginationRowModel,
  PaginationState,
} from '@tanstack/react-table';
import usePageQuery from '../../core/hooks/usePageQuery';
import { useGetAllInventoryQuery, useGetUserQuery } from '../posApi';
import useInventoryDetailsColumn from './useInventoryDetailsColumn';
import { IUserInfo } from '../../core/Interface/user.interface';
import {
  IInventoryDetails,
  IInventoryDetailsData,
} from '../../core/Interface/inventory.interface';
import React from 'react';

const calcPageSize = () => {
  const available = window.innerHeight - 306;
  return Math.max(5, Math.floor((available - 48) / 52));
};

const PAGE_SIZE = 5000;

const useInventoryDetails = (
  handleOpenStockAdjust: (product: IInventoryDetailsData) => void
) => {
  const { page } = usePageQuery();
  const [pagination, setPagination] = React.useState<PaginationState>({
    pageIndex: page,
    pageSize: calcPageSize(),
  });

  React.useEffect(() => {
    const handleResize = () => {
      setPagination((prev) => ({ ...prev, pageSize: calcPageSize() }));
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const [searchText, setSearchText] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('');
  const { data: companyData } = useGetUserQuery();

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) {
        return userData.company.currencyCode;
      }
    }
    return '';
  }, [companyData]);

  const {
    data: inventoryData,
    isLoading,
    isFetching,
    error,
  } = useGetAllInventoryQuery({
    pageIndex: 0,
    pageSize: PAGE_SIZE,
    searchText: '',
  });

  const allRecords = useMemo(() => {
    const d = inventoryData?.data as IInventoryDetails | undefined;
    return d?.records ?? [];
  }, [inventoryData]);

  const categories = useMemo(() => {
    const names = new Set<string>();
    allRecords.forEach((r) => {
      if (r.categoryName?.trim()) names.add(r.categoryName.trim());
    });
    return Array.from(names).sort((a, b) => a.localeCompare(b));
  }, [allRecords]);

  const filteredData = useMemo(() => {
    let result = allRecords;
    if (selectedCategory) {
      result = result.filter((r) => r.categoryName?.trim() === selectedCategory);
    }
    if (searchText) {
      const q = searchText.toLowerCase().trim();
      result = result.filter(
        (r) =>
          r.code?.toLowerCase().includes(q) ||
          r.name?.toLowerCase().includes(q)
      );
    }
    return result;
  }, [allRecords, selectedCategory, searchText]);

  // Reset to first page when filters change
  React.useEffect(() => {
    setPagination((prev) => ({ ...prev, pageIndex: 0 }));
  }, [searchText, selectedCategory]);

  const columns = useInventoryDetailsColumn(currencyCode, handleOpenStockAdjust);

  const table = useReactTable({
    data: error ? [] : filteredData,
    columns,
    state: { pagination },
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    manualPagination: false,
    initialState: { columnVisibility: { id: false } },
  });

  return {
    table,
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    error,
    totalCount: filteredData.length,
    categories,
    selectedCategory,
    setSelectedCategory,
    searchText,
    setSearchText,
  };
};

export default useInventoryDetails;
